#!/bin/bash
# lane-run.sh <T> <run>
T=$1; R=$T/$2; cd $T/driver
date -u +%FT%TZ > $R/logs/started
ulimit -u $(( $(ps -A | wc -l) + 1500 ))
exec nice -n 15 env -u TYPESAFE_API_KEY -u OPENAI_API_KEY -u CODEX_API_KEY -u ANTHROPIC_API_KEY -u HOMEBREW_GITHUB_API_TOKEN -u GH_TOKEN -u GITHUB_TOKEN -u CLAUDECODE -u CLAUDE_CODE_ENTRYPOINT -u CLAUDE_AFK_TIMEOUT_MS -u CLAUDE_CODE_MAX_SUBAGENTS_PER_SESSION -u CLAUDE_CODE_MESSAGING_SOCKET -u CLAUDE_CODE_MESSAGING_TOKEN -u CLAUDE_CODE_BRIDGE_SESSION_ID -u CLAUDE_CODE_EXECPATH -u CLAUDE_CODE_SESSION_ID -u CLAUDE_CODE_CHILD_SESSION -u CLAUDE_CODE_SESSION_ATTENDED -u CLAUDE_PID -u CLAUDE_EFFORT -u FABRIKA_FOREGROUND GH_CONFIG_DIR=$T/gh FABRIKA_HOME=$R/home PATH=$T/bin:$PATH node --disable-warning=ExperimentalWarning driver.ts $R $T/code > $R/logs/driver.out 2>&1
